\draw[->,thick] (O) -- (P) node[midway,above left] {$\underset{\sim}{v}_{A}$};
\draw[->,thick] (P) -- (Q) node[midway,right] {$-\underset{\sim}{v}_{B}$};
\draw[->,thick,dashed] (O) -- (Q) node[midway,below] {$\underset{\sim}{v}_{AB}$};
\end{tikzpicture}
[/tikz]

